solutionCode:
#[derive(Debug, PartialEq)]
pub enum Brinde {
    Nada,
    Vale(i32),
}

pub fn o_vale_do(brinde: Brinde) -> i32 {
    match brinde {
        Brinde::Vale(valor) => valor,
        Brinde::Nada => 0,
    }
}

testsCode:
use desafio::o_vale_do;
use desafio::Brinde;

#[test]
fn testa_o_vale_de_cinquenta() {
    assert_eq!(o_vale_do(Brinde::Vale(50)), 50);
}

#[test]
fn testa_o_vale_do_nada() {
    assert_eq!(o_vale_do(Brinde::Nada), 0);
}
